"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8236],{56010:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Constructs a new `PlacementSystem` instance.","params":[{"name":"buildAreaTag","desc":"CollectionService tag that marks valid build-area `BasePart`s.","lua_type":"string"},{"name":"gridSize","desc":"Stud interval for grid-snap; also sets `StudsPerTile` on grid Textures.","lua_type":"number"}],"returns":[{"desc":"","lua_type":"PlacementSystem"}],"function_type":"static","source":{"line":347,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}},{"name":"SetBuildMode","desc":"Activates or deactivates build mode.\\n\\nWhen `isActive` is `true`, grid `Texture` instances are created on every\\ntagged build-area part.  When `false`, those textures are destroyed and the\\ncurrent ghost model is cleared.\\n\\n:::caution Client only\\nThe server sets `IsBuildMode = true` directly to avoid creating `Texture`\\ninstances that would permanently replicate to clients.\\n:::","params":[{"name":"isActive","desc":"`true` to enter build mode, `false` to leave it.","lua_type":"boolean"}],"returns":[],"function_type":"method","source":{"line":395,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}},{"name":"SetGridMode","desc":"Switches between grid-snap (`true`) and free-placement (`false`) mode.\\n\\nFires `Signals.OnPlacementModeChanged` with the new boolean value so UI and\\nother systems can react without polling.","params":[{"name":"isGrid","desc":"`true` for grid-snap, `false` for free placement.","lua_type":"boolean"}],"returns":[],"function_type":"method","source":{"line":432,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}},{"name":"ClearGhostModel","desc":"Destroys the local ghost model and resets all ghost-related state\\n(`Rotation`, `IsValid`, `LastColor`, `TargetGhostCFrame`,\\n`CollisionBoxRelCFrame`, etc.) to their defaults.\\n\\nSafe to call when no ghost is active.","params":[{"name":"self","desc":"","lua_type":"PlacementSystem"}],"returns":[],"function_type":"static","source":{"line":453,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}},{"name":"SetGhostModel","desc":"Clones `template`, strips gameplay tags and ProximityPrompts, applies ghost\\nappearance, and sets it as the active ghost model.  Also precomputes\\ncollision-box relative CFrame data used by `CalculateGhostCFrame` and\\n`GetCollisionBox`.\\n\\n`ghostParent` defaults to `workspace` (client preview).  The server passes\\n`ServerStorage` so the validation ghost is never replicated to clients.","params":[{"name":"template","desc":"The source `PlaceableItem` model to clone.","lua_type":"Model"},{"name":"ghostParent","desc":"Parent for the cloned ghost; defaults to `workspace`.","lua_type":"Instance?"}],"returns":[],"function_type":"method","source":{"line":482,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}},{"name":"Rotate","desc":"Adds `degrees` to the current rotation, wrapping at 360.\\n\\nThe rotation is applied on the next `CalculateGhostCFrame` / `UpdateGhostPosition`\\ncall.","params":[{"name":"self","desc":"","lua_type":"PlacementSystem"},{"name":"degrees","desc":"Degrees to rotate (positive = counter-clockwise when viewed from above).","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":546,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}},{"name":"CalculateGhostCFrame","desc":"Returns the world-space pivot `CFrame` for the ghost model given a surface\\nposition.\\n\\nHeight is derived so the **bottom face of the CollisionBox** sits exactly at\\n`position.Y`, correcting for any Y offset between the model pivot and the\\ncollision box centre.  Returns `nil` when no ghost is active.","params":[{"name":"self","desc":"","lua_type":"PlacementSystem"},{"name":"position","desc":"World-space point on the top surface of a build-area part.","lua_type":"Vector3"}],"returns":[{"desc":"Ghost pivot CFrame, or `nil` if no ghost is set.","lua_type":"CFrame?"}],"function_type":"static","source":{"line":583,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}},{"name":"GetCollisionBox","desc":"Returns the world-space `CFrame` and `Size` of the collision volume for a\\ngiven ghost pivot `CFrame`.\\n\\nUses the precomputed relative CFrame cached by `SetGhostModel`.","params":[{"name":"ghostCFrame","desc":"The ghost model\'s current pivot CFrame.","lua_type":"CFrame"}],"returns":[{"desc":"World-space CFrame of the CollisionBox centre.","lua_type":"CFrame"},{"desc":"Size of the CollisionBox (slightly inset from the actual part size).","lua_type":"Vector3"}],"function_type":"method","source":{"line":606,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}},{"name":"BuildObstructionFilter","desc":"Builds the `OverlapParams` include-filter list used by `CheckValidity`.\\n\\nThe filter includes: every instance tagged `PlacementObstruction` (placed\\nitems and static world fixtures), the ghost-models folder, every\\nfaction-tagged NPC (`EnemyNPC` / `FriendlyNPC`, see Factions), and any\\n`extra` models supplied by the caller. Player characters are never\\nobstructions \u2014 `PlacementServer` pushes anyone standing in the way.","params":[{"name":"extra","desc":"Additional models to include in the obstruction check.","lua_type":"{ Model }?"}],"returns":[{"desc":"List of instances to pass to `OverlapParams.FilterDescendantsInstances`.","lua_type":"{ Instance }"}],"function_type":"method","source":{"line":631,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}},{"name":"CheckValidity","desc":"Returns `true` when the given collision box does not overlap any obstruction.\\n\\nUses `workspace:GetPartBoundsInBox` with an include-filter.  The local\\nghost\'s own parts (`GhostOwnParts`) are excluded so the ghost never blocks\\nitself.  Pass `filterOverride` to supply a pre-built filter (e.g. with other\\nplayers\' ghosts included); if omitted, `BuildObstructionFilter(nil)` is\\ncalled automatically.","params":[{"name":"boxCFrame","desc":"World-space CFrame of the collision box centre.","lua_type":"CFrame"},{"name":"boxSize","desc":"Size of the collision box.","lua_type":"Vector3"},{"name":"filterOverride","desc":"Custom include-filter; falls back to `BuildObstructionFilter` when `nil`.","lua_type":"{ Instance }?"}],"returns":[{"desc":"`true` if placement is valid (no obstructions).","lua_type":"boolean"}],"function_type":"method","source":{"line":670,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}},{"name":"ColorizeGhost","desc":"Smoothly transitions the ghost colour to the valid or invalid tint from\\n`PlacementConfig`.\\n\\nNo-ops when the colour is already the target value (`LastColor` comparison),\\navoiding redundant tweens each frame.","params":[{"name":"self","desc":"","lua_type":"PlacementSystem"},{"name":"isValid","desc":"`true` \u2192 valid colour; `false` \u2192 invalid colour.","lua_type":"boolean"}],"returns":[],"function_type":"static","source":{"line":704,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}},{"name":"UpdateGhostPosition","desc":"Moves the ghost to `position`, runs the collision validity check,\\ncolorizes the ghost, and returns the final world `CFrame`.\\n\\nFires `Signals.OnBuildValidityChanged` with the new boolean whenever\\n`IsValid` changes, so UI and audio systems can react without polling.\\n\\nCalled every `Heartbeat` tick on the client.","params":[{"name":"position","desc":"Surface position from `CalculatePlacement`.","lua_type":"Vector3"}],"returns":[{"desc":"The ghost pivot CFrame, or `nil` if no ghost is active.","lua_type":"CFrame?"}],"function_type":"method","source":{"line":736,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}},{"name":"LerpGhost","desc":"Smoothly interpolates the ghost model toward `TargetGhostCFrame` each frame.\\n\\nIn grid mode only rotation is interpolated (position snaps instantly in\\n`UpdateGhostPosition`).  In free mode, both position and rotation are\\nsmoothed using frame-rate-independent exponential decay.\\n\\nShould be called every `Heartbeat` with the frame delta time.","params":[{"name":"dt","desc":"Frame delta time in seconds.","lua_type":"number"}],"returns":[],"function_type":"method","source":{"line":788,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}},{"name":"SetOtherGhost","desc":"Creates, moves, or destroys the ghost preview for another player.\\n\\n- `isActive = true` with a `template` \u2014 clones and shows the ghost.\\n- `isActive = true` with a `cframe` \u2014 moves an existing ghost.\\n- `isActive = false` \u2014 destroys and removes the ghost entry.\\n\\n`template` is only required the first time `isActive = true` is called for\\na given player.","params":[{"name":"player","desc":"The player whose ghost to manage.","lua_type":"Player"},{"name":"isActive","desc":"`true` to show/move, `false` to hide/destroy.","lua_type":"boolean"},{"name":"cframe","desc":"Target position for the ghost this frame.","lua_type":"CFrame?"},{"name":"template","desc":"Source model to clone; only needed on first show.","lua_type":"Model?"}],"returns":[],"function_type":"method","source":{"line":829,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}},{"name":"GetSnappedPosition","desc":"Snaps `hitPosition` to the nearest grid vertex and clamps the result so the\\ncollision box never overhangs the build-area edge.\\n\\nUsed when `IsGridMode = true`.","params":[{"name":"hitPosition","desc":"Raw world-space raycast hit position.","lua_type":"Vector3"},{"name":"hitPart","desc":"The build-area part that was hit.","lua_type":"BasePart"}],"returns":[{"desc":"Grid-snapped, clamped world-space surface position.","lua_type":"Vector3"}],"function_type":"method","source":{"line":871,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}},{"name":"GetFreePosition","desc":"Returns a surface position with the raw X/Z of `hitPosition` locked to the\\nbuild-area surface Y, clamped so the collision box never overhangs the edge.\\n\\nUsed when `IsGridMode = false`.","params":[{"name":"hitPosition","desc":"Raw world-space raycast hit position.","lua_type":"Vector3"},{"name":"hitPart","desc":"The build-area part that was hit.","lua_type":"BasePart"}],"returns":[{"desc":"Clamped world-space surface position.","lua_type":"Vector3"}],"function_type":"method","source":{"line":896,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}},{"name":"CalculatePlacement","desc":"Raycasts against tagged build-area parts and returns the resolved surface\\nposition (grid-snapped or free, based on `IsGridMode`), or `nil` if no\\nbuild-area part was hit or `IsBuildMode` is `false`.\\n\\nThe raycast uses an include-filter limited to build-area parts, so placed\\nobjects are transparent to the ray.  Overlap with placed items is handled\\nseparately by `CheckValidity`.\\n\\nAlso caches the hit part as `self.LastBuildAreaPart` for callers that need\\nthe platform bounds afterward (e.g. push-out-of-the-way logic).","params":[{"name":"rayOrigin","desc":"World-space ray origin (typically the camera or mouse position).","lua_type":"Vector3"},{"name":"rayDirection","desc":"World-space ray direction (magnitude determines max distance).","lua_type":"Vector3"}],"returns":[{"desc":"Resolved surface position, or `nil` if no valid build area was hit.","lua_type":"Vector3?"}],"function_type":"method","source":{"line":930,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}},{"name":"Destroy","desc":"Cleans up all ghosts, grid textures, and tween state owned by this instance.\\n\\n`Signals` entries are global singletons and are **not** destroyed here.","params":[],"returns":[],"function_type":"method","source":{"line":963,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}}],"properties":[],"types":[],"name":"PlacementSystem","desc":"Shared placement and validation system used by both the client-side preview\\n(PlacementClient) and the server-side anti-exploit validator (PlacementServer).\\n\\nVisual-only features (TweenPlus colour transitions, grid Texture instances)\\nare guarded by `IS_CLIENT` checks inside each method, so the same object can\\nbe constructed on the server without side-effects.\\n\\n### Model structure\\nItems under `ReplicatedStorage/PlaceableItems` are expected to contain:\\n- **VisualMesh** \u2014 `MeshPart` or `Part`; visible geometry.\\n- **CollisionBox** \u2014 `Part`; axis-aligned collision volume used for overlap\\n  testing and height correction.\\n- **RootPart** *(optional)* \u2014 animation rig root; treated as\\n  `PlacementIgnore` and hidden.\\n\\nParts tagged `PlacementIgnore` are fully hidden and excluded from all\\ncollision checks.\\n\\n### Signals fired\\n- `Signals.OnBuildValidityChanged` \u2014 fired by `UpdateGhostPosition` when\\n  `IsValid` flips.\\n- `Signals.OnPlacementModeChanged` \u2014 fired by `SetGridMode` when the grid\\n  toggle changes.","source":{"line":169,"path":"src/ReplicatedStorage/SharedModules/PlacementSystem.luau"}}')}}]);